// ─── Shared Design Tokens ─────────────────────────────────────────────────────
const S = {
  bg:"#060b14",panel:"#0a0f1a",card:"#0f172a",border:"#1e293b",
  text:"#e2e8f0",muted:"#64748b",dim:"#475569",
  blue:"#3b82f6",green:"#22c55e",red:"#ef4444",amber:"#f59e0b",
  purple:"#a855f7",cyan:"#06b6d4",teal:"#14b8a6",orange:"#f97316",
};
const TC = {red:"#ef4444",amber:"#f59e0b",green:"#22c55e",blue:"#3b82f6",gray:"#6b7280"};

// ─── Math Helpers ─────────────────────────────────────────────────────────────
const ratio=(a,b)=>{const na=parseFloat(a),nb=parseFloat(b);return(!isNaN(na)&&!isNaN(nb)&&nb!==0)?(na/nb).toFixed(2):null};
const pctOf=(a,b)=>{const r=ratio(a,b);return r?((parseFloat(r)*100).toFixed(1)+"%"):null};
const pctCol=(v,hi=true,lo=0,high=15)=>{const n=parseFloat(v);if(isNaN(n))return TC.gray;return hi?(n>=high?TC.green:n>=lo?TC.amber:TC.red):(n<=lo?TC.green:n<=high?TC.amber:TC.red)};
const scCol=v=>{const n=parseFloat(v);return isNaN(n)?TC.gray:n>=4?TC.green:n>=2.5?TC.amber:TC.red};
const fmt=(v,d=2)=>{const n=parseFloat(v);if(isNaN(n))return"N/A";if(Math.abs(n)>=1e9)return`$${(n/1e9).toFixed(2)}B`;if(Math.abs(n)>=1e6)return`$${(n/1e6).toFixed(2)}M`;return n.toFixed(d)};
const pct=(v,d=2)=>{const n=parseFloat(v);return isNaN(n)?"N/A":`${(n*100).toFixed(d)}%`};
const gColor=v=>parseFloat(v)>0?S.green:S.red;
const normCDF=z=>{const t=1/(1+0.2316419*Math.abs(z));const d=0.3989422820*Math.exp(-z*z/2);let p=d*t*(0.3193815+t*(-0.3565638+t*(1.7814779+t*(-1.8212560+t*1.3302744))));return z>=0?1-p:p;};

// ─── Shared UI Components ─────────────────────────────────────────────────────
function Card({title,children,accent="#3b82f6",badge}){
  return(
    <div style={{background:S.card,border:`1px solid ${S.border}`,borderRadius:8,padding:"14px 16px",marginBottom:12,borderTop:`2px solid ${accent||S.blue}`}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
        <span style={{color:S.muted,fontSize:9,fontFamily:"monospace",letterSpacing:"0.1em",textTransform:"uppercase"}}>{title}</span>
        {badge&&<span style={{background:S.panel,color:S.blue,fontSize:9,fontFamily:"monospace",padding:"2px 7px",borderRadius:3,fontWeight:700}}>{badge}</span>}
      </div>
      {children}
    </div>
  );
}
function Row({label,value,color,tip}){
  const[show,setShow]=useState(false);
  return(
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"5px 0",borderBottom:`1px solid ${S.border}`,position:"relative"}}
      onMouseEnter={()=>setShow(true)} onMouseLeave={()=>setShow(false)}>
      <span style={{color:"#94a3b8",fontSize:11,fontFamily:"monospace"}}>
        {label}{tip&&<span style={{marginLeft:3,color:"#334155",fontSize:9,cursor:"help"}}>ⓘ</span>}
      </span>
      {show&&tip&&<div style={{position:"absolute",left:0,top:26,background:"#0a0f1a",border:"1px solid #334155",color:"#94a3b8",fontSize:10,padding:"7px 10px",borderRadius:4,zIndex:999,maxWidth:260,lineHeight:1.5,pointerEvents:"none"}}>{tip}</div>}
      <span style={{color:color||S.text,fontFamily:"monospace",fontSize:12,fontWeight:600}}>{value||"N/A"}</span>
    </div>
  );
}
function Field({label,value,onChange,suffix,width}){
  return(
    <div style={{marginBottom:7,width:width||"100%"}}>
      <label style={{display:"block",color:S.muted,fontSize:9,fontFamily:"monospace",marginBottom:3,textTransform:"uppercase",letterSpacing:"0.05em"}}>{label}</label>
      <div style={{display:"flex",alignItems:"center",background:S.panel,borderRadius:4,border:`1px solid ${S.border}`}}>
        <input type="text" value={value} onChange={e=>onChange(e.target.value)}
          style={{flex:1,background:"transparent",border:"none",color:S.text,fontFamily:"monospace",fontSize:11,padding:"5px 8px",outline:"none"}}/>
        {suffix&&<span style={{padding:"0 7px",color:S.dim,fontFamily:"monospace",fontSize:10}}>{suffix}</span>}
      </div>
    </div>
  );
}
function Sel({label,value,onChange,options}){
  return(
    <div style={{marginBottom:7}}>
      <label style={{display:"block",color:S.muted,fontSize:9,fontFamily:"monospace",marginBottom:3,textTransform:"uppercase",letterSpacing:"0.05em"}}>{label}</label>
      <select value={value||"N/A"} onChange={e=>onChange(e.target.value)}
        style={{width:"100%",background:S.panel,border:`1px solid ${S.border}`,borderRadius:4,color:S.text,fontFamily:"monospace",fontSize:11,padding:"5px 7px",outline:"none"}}>
        {options.map(o=><option key={o} value={o}>{o}</option>)}
      </select>
    </div>
  );
}
function ScoreBar({value}){
  const n=parseFloat(value);
  if(isNaN(n)||!value||value==="N/A")return (<span style={{color:S.dim,fontFamily:"monospace",fontSize:12}}>—</span>);
  const col=scCol(String(n));
  return (<span style={{color:col,fontFamily:"monospace",fontSize:12,fontWeight:600}}>{"█".repeat(Math.round(n))}{"░".repeat(5-Math.round(n))} {n}/5</span>);
}
function Grid({cols=2,children,gap=12}){
  return (<div style={{display:"grid",gridTemplateColumns:`repeat(${cols},1fr)`,gap,marginBottom:12}}>{children}</div>);
}
function Tag({label,color}){
  return (<span style={{background:`${color}22`,color,border:`1px solid ${color}44`,borderRadius:4,padding:"2px 7px",fontSize:10,fontFamily:"monospace",marginRight:4}}>{label}</span>);
}
function Res({label,value,color,note}){
  return(
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"5px 0",borderBottom:`1px solid ${S.border}`}}>
      <div><span style={{color:"#94a3b8",fontSize:11,fontFamily:"monospace"}}>{label}</span>
      {note&&<div style={{color:S.dim,fontSize:9,marginTop:1}}>{note}</div>}</div>
      <span style={{color:color||S.text,fontFamily:"monospace",fontSize:12,fontWeight:700}}>{value}</span>
    </div>
  );
}

