  const f2=x=>(x===null||isNaN(x))?"—":parseFloat(x).toFixed(2);
  const fpct=(x,dec=2)=>(x===null||isNaN(x))?"—":parseFloat(x).toFixed(dec)+"%";
  const gC=x=>parseFloat(x)>0?S.green:parseFloat(x)<0?S.red:S.muted;

  // ── Custom GARCH forecast from manual params ──────────────────────────────
  const customForecast=useMemo(()=>{
    const om=omega, al=alpha, be=beta_;
    const persist=al+be;
    if(persist>=1||persist<=0) return null;
    // Use last realized variance as seed (last vol^2)
    const lastVol=parseFloat(p.current_vol_ann_pct)/100/Math.sqrt(252);
    const lastVar=lastVol*lastVol;
    const uncondVar=om/(1-persist);
    const fc=[];
    let v=lastVar;
    for(let h=1;h<=Math.max(horizon,20);h++){
      v=om+persist*v; // simplified E[sigma^2_t+h]
      fc.push({
        h,
        var_daily:v,
        vol_daily:Math.sqrt(v)*100,
        vol_ann:Math.sqrt(v)*Math.sqrt(252)*100,
        mean_revert_pct:(v-uncondVar)/uncondVar*100,
      });
    }
    const hl=-Math.log(2)/Math.log(persist);
    return{fc,persist,hl,uncondVol:Math.sqrt(uncondVar)*Math.sqrt(252)*100,lastVol:lastVol*Math.sqrt(252)*100};
  },[omega,alpha,beta_,horizon,ticker]);

  // ── VaR from conditional vol ──────────────────────────────────────────────
  const cv_daily = parseFloat(p.current_vol_ann_pct)/Math.sqrt(252)/100;
